-- Installed stele definitions; fixed, configurable reward rotation.
CREATE TABLE dungeon_stele_definitions (stele_id integer PRIMARY KEY, configuration jsonb NOT NULL);
CREATE TABLE dungeon_stele_placements (map_id integer NOT NULL, object_id bigint NOT NULL, stele_id integer NOT NULL REFERENCES dungeon_stele_definitions, x integer NOT NULL,y integer NOT NULL,z integer NOT NULL,PRIMARY KEY(map_id,object_id));
CREATE TABLE dungeon_stele_selections (instance_id bigint NOT NULL REFERENCES dungeon_instances,stele_id integer NOT NULL REFERENCES dungeon_stele_definitions,revision bigint NOT NULL DEFAULT 1,selection jsonb NOT NULL,PRIMARY KEY(instance_id,stele_id));
CREATE TABLE dungeon_stele_leases (character_id bigint PRIMARY KEY REFERENCES characters,instance_id bigint NOT NULL REFERENCES dungeon_instances,map_id integer NOT NULL,object_id bigint NOT NULL,stele_id integer NOT NULL REFERENCES dungeon_stele_definitions,generation text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE dungeon_stele_encounters (fight_id integer PRIMARY KEY REFERENCES combat_fights,instance_id bigint NOT NULL REFERENCES dungeon_instances,snapshot jsonb NOT NULL);

CREATE FUNCTION reject_stele_encounter_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'stele encounter snapshots are immutable'; END;
$$;
CREATE TRIGGER dungeon_stele_encounters_immutable BEFORE UPDATE OR DELETE ON dungeon_stele_encounters FOR EACH ROW EXECUTE FUNCTION reject_stele_encounter_mutation();
